     realm: your-realm-name
     resource: your-client-id
     public-client: true
   ```

3. **Protect Endpoints with Annotations**:
   - Use annotations to protect your endpoints based on roles.

   ```java
   @RestController
   public class DataController {

       @GetMapping("/data")
       @RolesAllowed("user")
       public List<String> getData() {
           // Return non-sensitive data
           return Arrays.asList("data1", "data2");
       }

       @GetMapping("/sensitive-data")
       @RolesAllowed("restricted_access")
       public List<String> getSensitiveData() {
           // Return sensitive data
           return Arrays.asList("sensitive_data1", "sensitive_data2");
       }
   }
   ```

#### Example Using Node.js and Keycloak Connect

