                        },
                        'Module C': {
                            sh 'pytest -n 4 tests/module_c/'
                        }
                    )
                }
            }
        }

        stage('Publish Reports') {
            steps {
                // Publish test reports if needed
                sh 'pytest --junitxml=reports/junit.xml'
            }
        }
    }
}
```

### Explanation

1. **triggers { githubPush() }**: This directive tells Jenkins to listen for webhook triggers from GitHub.
2. **Checkout**: Checks out the code from the repository.
3. **Install Dependencies**: Installs the required Python packages listed in `requirements.txt`.
4. **Run Tests**: Runs the tests in parallel using `pytest-xdist`.
