import logging
from langdetect import detect
import spacy

# Configure logging
logging.basicConfig(level=logging.ERROR, filename='app.log', filemode='w', format='%(name)s - %(levelname)s - %(message)s')

class CodeSwitchError(Exception):
    def __init__(self, message):
        super().__init__(message)

def log_code_switch_error(error_message):
    logging.error(f"CodeSwitchError: {error_message}")

def detect_language(text):
    try:
        return detect(text)
    except Exception as e:
        raise CodeSwitchError(f"Failed to detect language for segment '{text}': {str(e)}")

def tokenize_text(text, language):
    nlp = spacy.load(language)
    doc = nlp(text)
    return [token.text for token in doc]

def process_mixed_language_query(query):
    segments = query.split()
    processed_segments = []

    for segment in segments:
        try:
            detected_language = detect_language(segment)
            if detected_language:
                processed_segment = tokenize_text(segment, detected_language)
                processed_segments.extend(processed_segment)
            else:
                # Handle unknown language segments
                processed_segments.append(segment)
        except CodeSwitchError as e:
            log_code_switch_error(str(e))

    return ' '.join(processed_segments)

def test_system(test_inputs):
    for query in test_inputs:
        try:
            processed_query = process_mixed_language_query(query)
        except CodeSwitchError as e:
            log_code_switch_error(str(e))

# Example usage
